#include <bits/stdc++.h>
#include <atcoder/modint>

using namespace std;

using mint = atcoder::modint998244353;

int main() {
    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    for (int &i: a) cin >> i;
    vector binom(k + 1, vector<mint>(k + 1));
    for (int i = 0; i <= k; i++) {
        binom[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            binom[i][j] = binom[i - 1][j] + binom[i - 1][j - 1];
        }
    }
    vector dp(n + 1, vector<mint>(k + 1));
    mint ans = 0;
    for (int i = 0; i < n; i++) {
        vector<mint> pw(k + 1); // pw[j] = (a[i])^j
        pw[0] = 1;
        for (int j = 0; j < k; j++) {
            pw[j + 1] = pw[j] * a[i];
        }
        dp[i][0] += 1;
        for (int j = 0; j <= k; j++) {
            for (int l = 0; j + l <= k; l++) {
                dp[i + 1][j + l] += dp[i][j] * binom[k - j][l] * pw[l];
            }
        }
        ans += dp[i + 1][k];
    }
    cout << ans.val() << endl;
}

#include <atcoder/all>
#include <bits/stdc++.h>

using mint = atcoder::modint998244353;
using poly = std::vector<mint>;

int k;
poly poly_exp(int a) {
    poly res(k + 1, 1);
    for (int i = 1; i <= k; i++)
        res[i] = res[i - 1] * mint::raw(a) / mint::raw(i);
    return res;
}
void multiply(poly &f, const poly &g) {
    f = atcoder::convolution(f, g);
    f.resize(k + 1);
}

int main() {
    int n;
    std::cin >> n >> k;

    mint ans = 0;
    poly sum(k + 1, 0);

    while (n--) {
        int a;
        std::cin >> a;
        sum[0]++;
        multiply(sum, poly_exp(a));
        ans += sum[k];
    }

    for (int i = 1; i <= k; i++)
        ans *= i;

    std::cout << ans.val() << std::endl;
}

