#include <bits/stdc++.h>
using namespace std;
#include <atcoder/all>
using mint = atcoder::modint998244353;
#define rep(i, n) for(int i = 0; i < n; i++)
int main() {
	cin.tie(nullptr);
	ios::sync_with_stdio(false);
	int n, m;
	cin >> n >> m;
	vector<mint> a(n + 1);
	rep(i, n) {
		int x;
		cin >> x;
		a[i + 1] = a[i] + x;
	}
	mint ans = 0;
	vector<vector<mint>> ar(m + 1, vector<mint>(n + 1));
	rep(i, n + 1) ar[0][i] = 1;
	for (int j = 1; j <= m; j++)
		rep(i, n + 1) ar[j][i] = a[i] * ar[j - 1][i];
	rep(k, m + 1) {
		mint c = 1;
		rep(i, m) c *= i + 1;
		rep(i, k) c /= i + 1;
		rep(i, m - k) c /= i + 1;
		mint s = 0;
		rep(i, n + 1) {
			ans += ar[m - k][i] * s * c;
			if (k & 1)
				s -= ar[k][i];
			else
				s += ar[k][i];
		}
	}
	cout << ans.val() << endl;
}
